// Plan:
// 1. Check if the input array is empty or has only one element.
// 2. If so, return an empty array.
// 3. Otherwise, iterate through the array, subtracting each element from the previous one.
// 4. Collect the results into a new array and return it.

// Implementation:
use serde_json::Value;

pub fn solve(input: Value) -> Value {
    if let Value::Array(arr) = input {
        if arr.len() <= 1 {
            return Value::Array(vec![]);
        }
        let mut result = Vec::with_capacity(arr.len() - 1);
        for window in arr.windows(2) {
            if let (Value::Number(n1), Value::Number(n2)) = (window[0], window[1]) {
                result.push(n2.as_i64().unwrap() - n1.as_i64().unwrap());
            }
        }
        Value::Array(result)
    } else {
        Value::Array(vec![])
    }
}
